hooks.command:
: prawduct-unloaded-tripwire
m="${CLAUDE_CONFIG_DIR:-$HOME/.claude}/plugins/installed_plugins.json"
case "$(uname -s 2>/dev/null)" in Darwin) d="/Library/Application Support/ClaudeCode" ;; MINGW*|MSYS*|CYGWIN*) d="C:/Program Files/ClaudeCode" ;; *) d="/etc/claude-code" ;; esac
if command -v python3 >/dev/null 2>&1; then
v=$(python3 -c 'import json,os,sys
f=os.path.expanduser(sys.argv[1]);p=os.path.realpath(sys.argv[2])
def out(v):
 print(v);sys.exit(0)
def en(s):
 try:x=json.loads(open(s,"rb").read().decode("utf-8"))
 except (IOError,OSError,ValueError):return None
 e=x.get("enabledPlugins") if isinstance(x,dict) else None
 if not isinstance(e,dict) or "prawduct@prawduct" not in e:return None
 return e["prawduct@prawduct"] is False
def act():
 S=[]
 for d in sys.argv[3:]:
  try:N=sorted(n for n in os.listdir(os.path.join(d,"managed-settings.d")) if n.endswith(".json") and not n.startswith("."))
  except (IOError,OSError):N=[]
  S.extend(os.path.join(d,"managed-settings.d",n) for n in reversed(N))
  S.append(os.path.join(d,"managed-settings.json"))
 c=os.path.join(p,".claude")
 S+=[os.path.join(c,"settings.local.json"),os.path.join(c,"settings.json"),os.path.join(os.path.dirname(os.path.dirname(f)),"settings.json")]
 for s in S:
  r=en(s)
  if r is None:continue
  out("disabled:"+s if r else "active")
 out("active")
def rd(x):
 try:return open(x).read().strip()
 except (IOError,OSError,ValueError):return ""
P=[p]
g=rd(os.path.join(p,".git"))
if g.startswith("gitdir:"):
 x=os.path.join(p,g[7:].strip());c=rd(os.path.join(x,"commondir"))
 c=os.path.realpath(os.path.join(x,c)) if c else ""
 if os.path.basename(c)==".git":P.append(os.path.dirname(c))
try:
 m=json.load(open(f))
except (IOError,OSError):
 out("unreadable" if os.path.exists(f) else "missing")
except ValueError:
 out("unreadable")
d=m.get("plugins") if isinstance(m,dict) else None
if not isinstance(d,dict):
 out("unreadable")
r=d.get("prawduct@prawduct")
if r is None:
 out("inactive")
if not isinstance(r,list):
 out("unreadable")
b=0
for x in r:
 if not isinstance(x,dict):
  b=1;continue
 if x.get("scope") in ("user","global"):
  act()
 q=x.get("projectPath")
 if not isinstance(q,str):
  b=1;continue
 if os.path.realpath(os.path.expanduser(q)) in P:
  act()
out("unreadable" if b else "inactive")' "$m" "${CLAUDE_PROJECT_DIR:-.}" "$d" 2>/dev/null) || v="python3 exited $?, so the check did not finish"
else v="python3 not found"; fi
case "$v" in
active) ;;
inactive) echo "PRAWDUCT GOVERNANCE IS NOT ACTIVE IN THIS SESSION. This repo is governed by Prawduct, but prawduct@prawduct is not installed for it in this Claude Code profile ($m): no session banner, no /prawduct:* skills, no Stop gates. Tell the user before any work, and do not imitate the gates by reading the plugin's files. Fix: run claude plugin install prawduct@prawduct in this repo, then restart the session. (Loaded the plugin with --plugin-dir? Then ignore this line.)" ;;
disabled:*) s="${v#disabled:}"; echo "PRAWDUCT GOVERNANCE IS SWITCHED OFF IN THIS SESSION. This repo is governed by Prawduct and prawduct@prawduct is installed, but enabledPlugins sets it to false in $s: no session banner, no /prawduct:* skills, no Stop gates. Tell the user in one line before any work; it may be deliberate (/prawduct:repo-disable), and then they need do nothing. Do not imitate the gates by reading the plugin's files. To switch it back on, set that entry to true or delete it, then restart the session. (Loaded the plugin with --plugin-dir? Then ignore this line.)" ;;
*) echo "PRAWDUCT: could not verify that prawduct@prawduct is installed for this repo ($v: $m). If no Prawduct session banner appeared at session start, governance is not loaded: tell the user before any work, and do not imitate its gates by reading the plugin's files." ;;
esac
exit 0
